int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n + 1), pref(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        pref[i] = pref[i - 1] + a[i];
    }

    // dp[l][r] = minimum cost to combine slimes l..r into one
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));

    // len = 2 to n
    for (int len = 2; len <= n; len++) {
        for (int l = 1; l + len - 1 <= n; l++) {
            int r = l + len - 1;
            dp[l][r] = LLONG_MAX;
            // sum of sizes from l to r
            long long sum = pref[r] - pref[l - 1];
            for (int k = l; k < r; k++) {
                dp[l][r] = min(dp[l][r], dp[l][k] + dp[k + 1][r] + sum);
            }
        }
    }

    cout << dp[1][n] << "\n";
    return 0;
}

