#define MAXN 405
#define INF 1e18

long long dp[MAXN][MAXN];
long long prefix[MAXN];
int a[MAXN];

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    prefix[0] = 0;
    for (int i = 0; i < n; i++) {
        prefix[i+1] = prefix[i] + a[i];
    }

    // Initialize dp
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) dp[i][j] = 0;
            else dp[i][j] = (long long)INF;
        }
    }

    // Fill by increasing length
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i <= n - len; i++) {
            int j = i + len - 1;
            long long sum = prefix[j+1] - prefix[i];
            for (int k = i; k < j; k++) {
                long long cost = dp[i][k] + dp[k+1][j] + sum;
                if (cost < dp[i][j]) {
                    dp[i][j] = cost;
                }
            }
        }
    }

    printf("%lld\n", dp[0][n-1]);

    return 0;
}

