#include <stdio.h>
#include <limits.h>

#define MAXN 405
#define INF ((long long)4e18)

long long dp[MAXN][MAXN];
long long pref[MAXN];

static inline long long sum(int l, int r) {
    return pref[r + 1] - pref[l];
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 0; i < N; i++) {
        long long x;
        scanf("%lld", &x);
        pref[i + 1] = pref[i] + x;
    }

    for (int len = 2; len <= N; len++) {
        for (int l = 0; l + len - 1 < N; l++) {
            int r = l + len - 1;
            dp[l][r] = INF;
            long long s = sum(l, r);
            for (int k = l; k < r; k++) {
                long long cand = dp[l][k] + dp[k + 1][r] + s;
                if (cand < dp[l][r]) dp[l][r] = cand;
            }
        }
    }

    printf("%lld\n", dp[0][N - 1]);
    return 0;
}
